/* =====================================================
   NOCTURNE — Dark Theme E-Commerce
   ===================================================== */

/* ---- Reset & base ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* Palette */
  --c-bg:          #0c0c0e;
  --c-surface-1:   #131316;
  --c-surface-2:   #1b1b20;
  --c-surface-3:   #242429;
  --c-border:      #2e2e35;
  --c-border-sub:  #1e1e24;

  --c-text:        #f0eee8;
  --c-text-muted:  #9896a4;
  --c-text-sub:    #6b6977;

  --c-accent:      #c8a96e;   /* warm gold */
  --c-accent-dim:  #8a7045;
  --c-accent-pale: #f5e9cc;

  --c-red:         #e05252;   /* sale badge */
  --c-green:       #4caf50;

  /* Typography */
  --font-serif:    'Georgia', 'Times New Roman', serif;
  --font-sans:     system-ui, -apple-system, 'Segoe UI', Helvetica, Arial, sans-serif;

  /* Spacing */
  --container:     1280px;
  --section-gap:   5rem;

  /* Radii */
  --radius-sm:     4px;
  --radius-md:     8px;
  --radius-lg:     16px;

  /* Transitions */
  --ease:          cubic-bezier(0.4, 0, 0.2, 1);
  --dur:           200ms;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

html {
  scroll-behavior: smooth;
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

body {
  background-color: var(--c-bg);
  color: var(--c-text);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }

ul { list-style: none; }

/* ---- Utility ---- */
.container {
  max-width: var(--container);
  margin-inline: auto;
  padding-inline: clamp(1rem, 5vw, 2.5rem);
}

.sr-only {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
.sr-only:focus,
.sr-only:active {
  clip: auto;
  clip-path: none;
  height: auto;
  overflow: visible;
  position: static;
  white-space: normal;
  width: auto;
}

.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  background: var(--c-accent);
  color: var(--c-bg);
  font-weight: 700;
  padding: 0.75rem 1.25rem;
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  transition: top var(--dur) var(--ease);
}
.skip-link:focus { top: 0; }

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  border: 2px solid transparent;
  transition: background var(--dur) var(--ease), color var(--dur) var(--ease), border-color var(--dur) var(--ease), transform var(--dur) var(--ease);
}
.btn:focus-visible { outline-offset: 4px; }
.btn:active { transform: scale(0.97); }

.btn-primary {
  background: var(--c-accent);
  color: var(--c-bg);
  border-color: var(--c-accent);
}
.btn-primary:hover { background: var(--c-accent-pale); border-color: var(--c-accent-pale); }

.btn-ghost {
  background: transparent;
  color: var(--c-text);
  border-color: var(--c-border);
}
.btn-ghost:hover { border-color: var(--c-accent); color: var(--c-accent); }

/* ---- Section shared ---- */
.section { padding-block: var(--section-gap); }

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.5rem;
  flex-wrap: wrap;
}

.section-header h2 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 400;
  letter-spacing: -0.02em;
}

.section-sub {
  color: var(--c-text-muted);
  font-size: 0.9rem;
}

.section-link {
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--c-accent);
  white-space: nowrap;
  transition: color var(--dur) var(--ease);
}
.section-link:hover { color: var(--c-accent-pale); }

/* =====================================================
   HEADER
   ===================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(12, 12, 14, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--c-border-sub);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding-block: 1rem;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}
.logo-mark { color: var(--c-accent); font-size: 1.1rem; }
.logo-text  {
  font-family: var(--font-serif);
  font-size: 1.1rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

/* Primary nav */
nav[aria-label="Primary"] { flex: 1; display: flex; justify-content: center; }

.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  color: var(--c-text);
  flex-direction: column;
  gap: 5px;
}
.hamburger,
.hamburger::before,
.hamburger::after {
  display: block;
  width: 22px;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform var(--dur) var(--ease), opacity var(--dur) var(--ease);
}
.hamburger { position: relative; }
.hamburger::before,
.hamburger::after {
  content: '';
  position: absolute;
  left: 0;
}
.hamburger::before { top: -6px; }
.hamburger::after  { top:  6px; }

.nav-toggle[aria-expanded="true"] .hamburger { background: transparent; }
.nav-toggle[aria-expanded="true"] .hamburger::before { transform: rotate(45deg) translate(4px, 4px); }
.nav-toggle[aria-expanded="true"] .hamburger::after  { transform: rotate(-45deg) translate(4px, -4px); }

.nav-list {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-list > li { position: relative; }

.nav-list a,
.submenu-trigger {
  display: block;
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--c-text-muted);
  letter-spacing: 0.02em;
  background: none;
  border: none;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: color var(--dur) var(--ease), background var(--dur) var(--ease);
  white-space: nowrap;
}
.nav-list a:hover,
.submenu-trigger:hover,
.nav-list a[aria-current="page"] {
  color: var(--c-text);
  background: var(--c-surface-2);
}
.nav-list a[aria-current="page"] {
  text-decoration: underline;
  text-decoration-color: var(--c-accent);
  text-underline-offset: 4px;
}

.chevron { font-style: normal; transition: transform var(--dur) var(--ease); }
.submenu-trigger[aria-expanded="true"] .chevron { transform: rotate(-180deg); }

.submenu {
  position: absolute;
  top: calc(100% + 0.5rem);
  left: 0;
  min-width: 180px;
  background: var(--c-surface-2);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 0.5rem;
  box-shadow: 0 8px 32px rgba(0,0,0,0.5);
}
.submenu li a {
  border-radius: var(--radius-sm);
  color: var(--c-text-muted);
}
.submenu li a:hover { color: var(--c-text); background: var(--c-surface-3); }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: 0.25rem; margin-left: auto; }

.icon-btn {
  position: relative;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--c-text-muted);
  padding: 0.5rem;
  border-radius: var(--radius-sm);
  transition: color var(--dur) var(--ease), background var(--dur) var(--ease);
  display: flex;
  align-items: center;
  justify-content: center;
}
.icon-btn:hover { color: var(--c-text); background: var(--c-surface-2); }

.cart-count {
  position: absolute;
  top: 2px;
  right: 2px;
  background: var(--c-accent);
  color: var(--c-bg);
  font-size: 0.6rem;
  font-weight: 700;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* =====================================================
   HERO
   ===================================================== */
.hero {
  position: relative;
  min-height: clamp(480px, 85vh, 900px);
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 80% at 70% 50%, rgba(200, 169, 110, 0.08) 0%, transparent 60%),
    radial-gradient(ellipse 60% 100% at 100% 100%, rgba(100, 80, 180, 0.06) 0%, transparent 60%),
    linear-gradient(160deg, #0c0c0e 0%, #16141c 50%, #0c0c0e 100%);
}

.hero-pattern {
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 79px,
      rgba(255,255,255,0.015) 79px,
      rgba(255,255,255,0.015) 80px
    ),
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 79px,
      rgba(255,255,255,0.015) 79px,
      rgba(255,255,255,0.015) 80px
    );
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 660px;
  padding-block: 6rem;
}

.hero-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--c-accent);
  margin-bottom: 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.hero-eyebrow::before {
  content: '';
  display: block;
  width: 2.5rem;
  height: 1px;
  background: var(--c-accent);
}

.hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 7vw, 5.5rem);
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: 1.5rem;
}
.hero h1 em {
  font-style: italic;
  color: var(--c-accent);
}

.hero-sub {
  font-size: 1.0625rem;
  color: var(--c-text-muted);
  max-width: 42ch;
  margin-bottom: 2.5rem;
  line-height: 1.7;
}

.hero-ctas { display: flex; gap: 1rem; flex-wrap: wrap; }

.hero-scroll-cue {
  position: absolute;
  bottom: 2rem;
  left: clamp(1rem, 5vw, 2.5rem);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--c-text-sub);
  font-size: 0.7rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}
.scroll-line {
  width: 1px;
  height: 2.5rem;
  background: linear-gradient(to bottom, transparent, var(--c-text-sub));
  animation: scrollPulse 2s infinite;
}
@keyframes scrollPulse {
  0%, 100% { opacity: 0.3; }
  50%       { opacity: 1; }
}

/* =====================================================
   MARQUEE BAR
   ===================================================== */
.marquee-bar {
  background: var(--c-surface-1);
  border-block: 1px solid var(--c-border-sub);
  padding-block: 0.75rem;
  overflow: hidden;
  white-space: nowrap;
}

.marquee-track {
  display: inline-flex;
  gap: 3rem;
  animation: marquee 30s linear infinite;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-text-muted);
}
.marquee-track span[aria-hidden="true"] { color: var(--c-accent); }

@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* =====================================================
   FEATURED PRODUCTS
   ===================================================== */
.featured-products { background: var(--c-bg); }

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

/* Large card spans 2 columns and 2 rows */
.product-card--large {
  grid-column: span 2;
  grid-row: span 2;
}

.product-card {
  border-radius: var(--radius-lg);
  background: var(--c-surface-1);
  border: 1px solid var(--c-border-sub);
  overflow: hidden;
  transition: border-color var(--dur) var(--ease), transform var(--dur) var(--ease), box-shadow var(--dur) var(--ease);
}
.product-card:hover {
  border-color: var(--c-border);
  transform: translateY(-3px);
  box-shadow: 0 16px 40px rgba(0,0,0,0.4);
}

.product-card__link {
  display: flex;
  flex-direction: column;
  height: 100%;
}
.product-card__link:focus-visible { border-radius: var(--radius-lg); }

/* Product image placeholder with themed gradients */
.product-card__img-wrap {
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}

.product-card--large .product-card__img-wrap { height: 420px; }
.product-card:not(.product-card--large)      .product-card__img-wrap { height: 220px; }

.product-card__img {
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  transition: transform 400ms var(--ease);
}
.product-card:hover .product-card__img { transform: scale(1.04); }

/* Themed product image gradients */
.product-img-1 { background: linear-gradient(135deg, #1a1820 0%, #2c2438 40%, #191524 100%); }
.product-img-2 { background: linear-gradient(135deg, #1c1c22 0%, #2a2a32 100%); }
.product-img-3 { background: linear-gradient(135deg, #141820 0%, #1e2430 100%); }
.product-img-4 { background: linear-gradient(135deg, #231a10 0%, #3a2a15 100%); }
.product-img-5 { background: linear-gradient(135deg, #120f18 0%, #1e1830 100%); }

/* Add abstract shapes for visual interest */
.product-img-1::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 70%, rgba(200,169,110,0.15) 0%, transparent 50%),
    radial-gradient(circle at 80% 20%, rgba(100,80,180,0.12) 0%, transparent 40%);
}
.product-img-2::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 60% 50%, rgba(180,180,200,0.08) 0%, transparent 60%);
}
.product-img-3::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 40% 80%, rgba(70,100,160,0.15) 0%, transparent 55%);
}
.product-img-4::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 40%, rgba(200,130,60,0.2) 0%, transparent 55%);
}
.product-img-5::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(150,100,220,0.15) 0%, transparent 50%);
}

/* Product silhouette hint */
.product-img-1::before,
.product-img-3::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 55%;
  height: 85%;
  background: rgba(255,255,255,0.03);
  clip-path: polygon(25% 0%, 75% 0%, 90% 15%, 90% 100%, 10% 100%, 10% 15%);
  border-top: 1px solid rgba(255,255,255,0.05);
}

.product-badge {
  position: absolute;
  top: 0.875rem;
  left: 0.875rem;
  padding: 0.25rem 0.6rem;
  background: var(--c-accent);
  color: var(--c-bg);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
}
.product-badge--hot { background: var(--c-red); color: #fff; }

.product-wishlist {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  background: rgba(12,12,14,0.7);
  border: 1px solid var(--c-border);
  color: var(--c-text-muted);
  border-radius: 50%;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  backdrop-filter: blur(8px);
  transition: color var(--dur) var(--ease), background var(--dur) var(--ease), border-color var(--dur) var(--ease);
  /* Don't let the button inherit the <a> link underline */
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] {
  color: var(--c-red);
  border-color: var(--c-red);
  background: rgba(224,82,82,0.12);
}
.product-wishlist[aria-pressed="true"] svg { fill: var(--c-red); stroke: var(--c-red); }

.product-card__body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  flex: 1;
}

.product-category {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-accent);
}

.product-name {
  font-family: var(--font-serif);
  font-weight: 400;
  font-size: 1.125rem;
  line-height: 1.2;
}

.product-desc {
  font-size: 0.8125rem;
  color: var(--c-text-muted);
  line-height: 1.5;
  flex: 1;
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.5rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--c-border-sub);
}

.product-price {
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--c-text);
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}
.stars { color: var(--c-accent); font-size: 0.75rem; letter-spacing: -1px; }
.rating-count { font-size: 0.75rem; color: var(--c-text-sub); }

/* =====================================================
   DEALS
   ===================================================== */
.deals { background: var(--c-surface-1); }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}
.deal-card--primary { grid-column: 1; grid-row: 1; }

.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  border: 1px solid var(--c-border-sub);
  overflow: hidden;
  min-height: 320px;
  display: flex;
  flex-direction: column;
  transition: transform var(--dur) var(--ease), box-shadow var(--dur) var(--ease), border-color var(--dur) var(--ease);
}
.deal-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 20px 48px rgba(0,0,0,0.5);
  border-color: var(--c-border);
}

.deal-card__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.deal-bg-1 {
  background: linear-gradient(135deg, #1a1520 0%, #231a30 50%, #14101e 100%);
}
.deal-bg-1::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 80% 20%, rgba(200,169,110,0.15) 0%, transparent 50%),
    radial-gradient(circle at 10% 90%, rgba(120,80,200,0.1) 0%, transparent 40%);
}
.deal-bg-2 {
  background: linear-gradient(135deg, #121820 0%, #1a2030 100%);
}
.deal-bg-2::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 70% 30%, rgba(80,120,200,0.1) 0%, transparent 55%);
}
.deal-bg-3 {
  background: linear-gradient(135deg, #0e1814 0%, #162018 100%);
}
.deal-bg-3::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 70%, rgba(80,180,120,0.1) 0%, transparent 50%);
}

.deal-card__content {
  position: relative;
  z-index: 1;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  height: 100%;
}

.deal-eyebrow {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--c-accent);
}

.deal-title {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.deal-desc {
  font-size: 0.875rem;
  color: var(--c-text-muted);
  flex: 1;
}

/* Countdown */
.deal-countdown {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-block: 0.25rem;
}
.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 48px;
  background: rgba(0,0,0,0.3);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-sm);
  padding: 0.4rem 0.5rem;
}
.countdown-num {
  font-size: 1.25rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--c-accent);
}
.countdown-label {
  font-size: 0.55rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--c-text-sub);
  margin-top: 2px;
}
.countdown-sep {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--c-accent);
  line-height: 1;
  align-self: flex-start;
  padding-top: 0.35rem;
}

/* =====================================================
   CATEGORIES
   ===================================================== */
.categories { padding-block: 3rem; background: var(--c-bg); }

.category-list {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.category-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.625rem;
  padding: 1.25rem 1.5rem;
  background: var(--c-surface-1);
  border: 1px solid var(--c-border-sub);
  border-radius: var(--radius-lg);
  color: var(--c-text-muted);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  min-width: 100px;
  transition: background var(--dur) var(--ease), border-color var(--dur) var(--ease), color var(--dur) var(--ease), transform var(--dur) var(--ease);
}
.category-item:hover {
  background: var(--c-surface-2);
  border-color: var(--c-border);
  color: var(--c-text);
  transform: translateY(-2px);
}
.category-icon { font-size: 1.75rem; line-height: 1; }

/* =====================================================
   EDITORIAL
   ===================================================== */
.editorial { background: var(--c-surface-1); }

.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.5rem;
}

.editorial-card--hero {
  grid-row: span 2;
}

.editorial-card {
  border-radius: var(--radius-lg);
  background: var(--c-surface-2);
  border: 1px solid var(--c-border-sub);
  overflow: hidden;
  transition: transform var(--dur) var(--ease), border-color var(--dur) var(--ease), box-shadow var(--dur) var(--ease);
}
.editorial-card:hover {
  transform: translateY(-3px);
  border-color: var(--c-border);
  box-shadow: 0 16px 40px rgba(0,0,0,0.4);
}

.editorial-card__link {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.editorial-img {
  background-size: cover;
  background-position: center;
  flex-shrink: 0;
  transition: transform 400ms var(--ease);
}
.editorial-card:hover .editorial-img { transform: scale(1.03); }

.editorial-card--hero .editorial-img { height: 320px; }
.editorial-card:not(.editorial-card--hero) .editorial-img { height: 180px; }

.editorial-img-1 {
  background: linear-gradient(160deg, #18141e 0%, #26203a 50%, #16121e 100%);
  position: relative;
}
.editorial-img-1::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 60% 40%, rgba(200,169,110,0.12) 0%, transparent 60%),
    radial-gradient(ellipse at 20% 80%, rgba(100,80,180,0.15) 0%, transparent 50%);
}
.editorial-img-2 {
  background: linear-gradient(160deg, #1e1410 0%, #2c1e14 100%);
  position: relative;
}
.editorial-img-2::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, rgba(200,130,60,0.18) 0%, transparent 60%);
}
.editorial-img-3 {
  background: linear-gradient(160deg, #12181e 0%, #1a2030 100%);
  position: relative;
}
.editorial-img-3::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 40%, rgba(80,120,200,0.12) 0%, transparent 55%);
}

.editorial-card__body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  flex: 1;
}

.editorial-tag {
  display: inline-block;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--c-accent);
}

.editorial-title {
  font-family: var(--font-serif);
  font-weight: 400;
  line-height: 1.25;
  letter-spacing: -0.02em;
}
.editorial-card--hero .editorial-title { font-size: 1.5rem; }
.editorial-card:not(.editorial-card--hero) .editorial-title { font-size: 1.125rem; }

.editorial-excerpt {
  font-size: 0.875rem;
  color: var(--c-text-muted);
  line-height: 1.6;
  flex: 1;
}

.editorial-meta {
  font-size: 0.75rem;
  color: var(--c-text-sub);
  letter-spacing: 0.02em;
}

/* =====================================================
   NEWSLETTER
   ===================================================== */
.newsletter {
  background: var(--c-bg);
  border-top: 1px solid var(--c-border-sub);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.newsletter-copy h2 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  margin-bottom: 0.75rem;
}
.newsletter-copy p { color: var(--c-text-muted); font-size: 0.9375rem; }

.form-field { display: flex; flex-direction: column; gap: 0.5rem; }

.form-field label {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--c-text-muted);
  letter-spacing: 0.04em;
}

.input-group {
  display: flex;
  gap: 0;
  border: 1px solid var(--c-border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  transition: border-color var(--dur) var(--ease), box-shadow var(--dur) var(--ease);
}
.input-group:focus-within {
  border-color: var(--c-accent);
  box-shadow: 0 0 0 3px rgba(200,169,110,0.15);
}

.input-group input {
  flex: 1;
  background: var(--c-surface-1);
  border: none;
  color: var(--c-text);
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  padding: 0.75rem 1rem;
  min-width: 0;
  outline: none;
}
.input-group input::placeholder { color: var(--c-text-sub); }

.input-group .btn { border-radius: 0; border: none; flex-shrink: 0; }
.input-group .btn:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: -2px;
}

.form-hint {
  font-size: 0.75rem;
  color: var(--c-text-sub);
  line-height: 1.4;
}

.form-error {
  font-size: 0.8rem;
  color: var(--c-red);
}

.form-status {
  font-size: 0.875rem;
  min-height: 1.5rem;
  color: var(--c-green);
  grid-column: 1 / -1;
  padding-top: 0.25rem;
}

/* =====================================================
   FOOTER
   ===================================================== */
.site-footer {
  background: var(--c-surface-1);
  border-top: 1px solid var(--c-border-sub);
}

.footer-inner {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 4rem;
  padding-block: 4rem;
}

.footer-brand { display: flex; flex-direction: column; gap: 1rem; }

.footer-tagline {
  font-size: 0.875rem;
  color: var(--c-text-sub);
  line-height: 1.6;
}

.social-links { display: flex; gap: 0.5rem; }
.social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--c-surface-2);
  border: 1px solid var(--c-border-sub);
  color: var(--c-text-muted);
  transition: background var(--dur) var(--ease), color var(--dur) var(--ease), border-color var(--dur) var(--ease);
}
.social-link:hover { background: var(--c-surface-3); color: var(--c-text); border-color: var(--c-border); }

.footer-nav {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.footer-nav-heading {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-text-muted);
  margin-bottom: 1rem;
}

.footer-nav ul { display: flex; flex-direction: column; gap: 0.625rem; }
.footer-nav a {
  font-size: 0.875rem;
  color: var(--c-text-sub);
  transition: color var(--dur) var(--ease);
}
.footer-nav a:hover { color: var(--c-text); }

.footer-bottom {
  border-top: 1px solid var(--c-border-sub);
  padding-block: 1.5rem;
}

.footer-bottom-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.footer-legal { font-size: 0.8rem; color: var(--c-text-sub); }

.footer-legal-links {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}
.footer-legal-links a {
  font-size: 0.8rem;
  color: var(--c-text-sub);
  transition: color var(--dur) var(--ease);
}
.footer-legal-links a:hover { color: var(--c-text); }

/* =====================================================
   RESPONSIVE
   ===================================================== */

/* Tablet — ≤ 1024px */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr 1fr;
  }
  .product-card--large {
    grid-column: span 2;
    grid-row: span 1;
  }
  .product-card--large .product-card__img-wrap { height: 280px; }

  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--primary { grid-column: span 2; }

  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--hero { grid-row: span 1; }

  .footer-inner { grid-template-columns: 1fr; gap: 2.5rem; }
  .footer-nav { grid-template-columns: repeat(3, 1fr); }
}

/* Mobile — ≤ 700px */
@media (max-width: 700px) {
  :root { --section-gap: 3rem; }

  /* Nav */
  nav[aria-label="Primary"] { order: 3; width: 100%; justify-content: flex-start; }
  .header-inner { flex-wrap: wrap; }
  .nav-toggle { display: flex; }

  .nav-list {
    flex-direction: column;
    align-items: flex-start;
    width: 100%;
    padding: 0.75rem 0 1rem;
    gap: 0;
    display: none;
  }
  .nav-list.is-open { display: flex; }
  .nav-list > li { width: 100%; }
  .nav-list a,
  .submenu-trigger { width: 100%; text-align: left; }
  .submenu { position: static; border: none; background: var(--c-surface-3); margin-left: 1rem; }

  .header-actions { margin-left: 0; }
  .logo { margin-right: auto; }

  /* Products */
  .product-grid { grid-template-columns: 1fr; }
  .product-card--large { grid-column: span 1; }
  .product-card--large .product-card__img-wrap { height: 260px; }

  /* Deals */
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--primary { grid-column: span 1; }

  /* Categories */
  .category-list { gap: 0.75rem; }
  .category-item { min-width: 80px; padding: 1rem; }

  /* Newsletter */
  .newsletter-inner { grid-template-columns: 1fr; gap: 1.5rem; }

  /* Footer */
  .footer-nav { grid-template-columns: 1fr 1fr; }
  .footer-bottom-inner { flex-direction: column; align-items: flex-start; }
}

/* Narrow (320px reflow) */
@media (max-width: 400px) {
  .hero-ctas { flex-direction: column; }
  .input-group { flex-direction: column; border-radius: var(--radius-md); }
  .input-group .btn { border-radius: 0 0 var(--radius-sm) var(--radius-sm); }
  .footer-nav { grid-template-columns: 1fr; }
}

/* Forced colors (high contrast) */
@media (forced-colors: active) {
  .product-card,
  .deal-card,
  .editorial-card,
  .category-item {
    border: 2px solid ButtonText;
  }
  .btn-primary {
    background: ButtonText;
    color: ButtonFace;
    border-color: ButtonText;
  }
  .product-badge,
  .deal-eyebrow,
  .editorial-tag { color: Highlight; }
  .logo-mark,
  .hero h1 em,
  .countdown-num { color: Highlight; }
  .scroll-line { display: none; }
  .marquee-track { animation: none; }
}

