  box-shadow: 0 0 0 3px rgba(200,169,110,0.15);
}

.input-group input {
  flex: 1;
  background: var(--c-surface-1);
  border: none;
  color: var(--c-text);
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  padding: 0.75rem 1rem;
  min-width: 0;
  outline: none;
}
.input-group input::placeholder { color: var(--c-text-sub); }

.input-group .btn { border-radius: 0; border: none; flex-shrink: 0; }
.input-group .btn:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: -2px;
}

.form-hint {
  font-size: 0.75rem;
  color: var(--c-text-sub);
  line-height: 1.4;
}

.form-error {
  font-size: 0.8rem;
  color: var(--c-red);
}

.form-status {
  font-size: 0.875rem;
  min-height: 1.5rem;
  color: var(--c-green);
