/* ===================================================== */

(function () {
  'use strict';

  /* ---- Mobile nav toggle ---- */
  const navToggle = document.querySelector('.nav-toggle');
  const navList   = document.getElementById('primary-nav-list');

  if (navToggle && navList) {
    navToggle.addEventListener('click', () => {
      const expanded = navToggle.getAttribute('aria-expanded') === 'true';
      navToggle.setAttribute('aria-expanded', String(!expanded));
      navList.classList.toggle('is-open', !expanded);
    });

    // Close on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && navToggle.getAttribute('aria-expanded') === 'true') {
        navToggle.setAttribute('aria-expanded', 'false');
        navList.classList.remove('is-open');
        navToggle.focus();
      }
    });
  }

  /* ---- Submenu triggers ---- */
  const submenuTriggers = document.querySelectorAll('.submenu-trigger');

  submenuTriggers.forEach((trigger) => {
    const submenuId = trigger.getAttribute('aria-controls');
    const submenu   = document.getElementById(submenuId);
    if (!submenu) return;

    trigger.addEventListener('click', () => {
      const expanded = trigger.getAttribute('aria-expanded') === 'true';
      // Close all other open submenus
      submenuTriggers.forEach((t) => {
        if (t !== trigger) {
          t.setAttribute('aria-expanded', 'false');
          const sm = document.getElementById(t.getAttribute('aria-controls'));
          if (sm) sm.hidden = true;
        }
      });
      trigger.setAttribute('aria-expanded', String(!expanded));
      submenu.hidden = expanded;
      if (!expanded) {
        // Focus first item when opening
        const firstLink = submenu.querySelector('a');
        if (firstLink) firstLink.focus();
      }
    });

    // Close submenu on Escape
    submenu.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        trigger.setAttribute('aria-expanded', 'false');
        submenu.hidden = true;
        trigger.focus();
      }
    });
  });

  // Close submenus when clicking outside
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.has-submenu')) {
      submenuTriggers.forEach((t) => {
        t.setAttribute('aria-expanded', 'false');
        const sm = document.getElementById(t.getAttribute('aria-controls'));
        if (sm) sm.hidden = true;
      });
    }
  });

  /* ---- Wishlist toggle ---- */
  const wishlistBtns = document.querySelectorAll('.product-wishlist');

  wishlistBtns.forEach((btn) => {
    btn.addEventListener('click', (e) => {
      // Prevent the parent <a> from navigating
      e.preventDefault();
      e.stopPropagation();

      const pressed = btn.getAttribute('aria-pressed') === 'true';
      btn.setAttribute('aria-pressed', String(!pressed));

      // Update label to reflect new state
      const currentLabel = btn.getAttribute('aria-label') || '';
      if (!pressed) {
        btn.setAttribute('aria-label', currentLabel.replace('Add ', 'Remove ').replace(' to wishlist', ' from wishlist'));
      } else {
        btn.setAttribute('aria-label', currentLabel.replace('Remove ', 'Add ').replace(' from wishlist', ' to wishlist'));
      }
    });
  });

  /* ---- Deal countdown timer ---- */
  function initCountdown() {
    // Set a target ~8.5 hours from page load for demo purposes
    const target = new Date(Date.now() + (8 * 3600 + 24 * 60) * 1000);

    const hoursEl   = document.querySelector('[data-unit="hours"]');
    const minutesEl = document.querySelector('[data-unit="minutes"]');
    const secondsEl = document.querySelector('[data-unit="seconds"]');

    if (!hoursEl || !minutesEl || !secondsEl) return;

    const pad = (n) => String(n).padStart(2, '0');

    // Announce countdown changes only once per minute to avoid noise
    let lastAnnouncedMinute = -1;

    function tick() {
      const diff = target - Date.now();
      if (diff <= 0) {
        hoursEl.textContent   = '00';
        minutesEl.textContent = '00';
        secondsEl.textContent = '00';
        return; // stop ticking
      }

      const totalSecs = Math.floor(diff / 1000);
      const h = Math.floor(totalSecs / 3600);
      const m = Math.floor((totalSecs % 3600) / 60);
      const s = totalSecs % 60;

      hoursEl.textContent   = pad(h);
      minutesEl.textContent = pad(m);
      secondsEl.textContent = pad(s);

      // Accessible live region — announce every minute
      if (m !== lastAnnouncedMinute) {
        lastAnnouncedMinute = m;
        const countdown = document.getElementById('countdown-1');
        if (countdown) {
          countdown.setAttribute('aria-label', `Flash sale ends in ${h} hours and ${m} minutes`);
        }
      }

      setTimeout(tick, 1000);
    }

    tick();
  }

