  const newsletterForm   = document.querySelector('.newsletter-form');
  const emailInput       = document.getElementById('email-input');
  const emailError       = document.getElementById('email-error');
  const newsletterStatus = document.getElementById('newsletter-status');

  if (newsletterForm && emailInput) {
    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      emailError.hidden = true;
      emailError.textContent = '';
      newsletterStatus.textContent = '';

      const val = emailInput.value.trim();
      const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      if (!val) {
        showEmailError('Please enter your email address.');
        return;
      }
      if (!emailRe.test(val)) {
        showEmailError('Please enter a valid email address, e.g. you@example.com.');
        return;
      }

      // Simulate async submission
      const submitBtn = newsletterForm.querySelector('[type="submit"]');
      submitBtn.disabled = true;
      submitBtn.textContent = 'Subscribing…';

      setTimeout(() => {
        submitBtn.disabled = false;
        submitBtn.textContent = 'Subscribe';
        emailInput.value = '';
        // Success message in live region
        newsletterStatus.textContent = '✓ You\'re subscribed. Welcome to NOCTURNE.';
      }, 900);
    });

    emailInput.addEventListener('input', () => {
      if (!emailError.hidden) {
        emailError.hidden = true;
        emailError.textContent = '';
        emailInput.removeAttribute('aria-invalid');
      }
    });
  }

