const { chromium } = require('/tmp/node_modules/playwright');
const fs = require('fs');
const path = require('path');

const PAGE_DIR = '/workspace/sandbox/skills/building-accessible-ui/shopping-home-page--framework-vanilla-js--style-dark/claude-sonnet-4.6__s3';
const html = fs.readFileSync(path.join(PAGE_DIR, 'index.html'), 'utf8');

// Inline CSS and JS so Playwright can serve everything from memory
const css = fs.readFileSync(path.join(PAGE_DIR, 'styles.css'), 'utf8');
const js  = fs.readFileSync(path.join(PAGE_DIR, 'main.js'),   'utf8');

const inlined = html
  .replace('<link rel="stylesheet" href="styles.css" />', `<style>${css}</style>`)
  .replace('<script src="main.js"></script>',             `<script>${js}</script>`);

(async () => {
  const browser = await chromium.launch();
  const page    = await browser.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const results = await page.evaluate('async () => await window.axe.run()');
  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = results.violations.filter(v =>  v.tags.includes('best-practice'));

  const fmt = v => ({
    id:      v.id,
    impact:  v.impact,
    desc:    v.description,
    help:    v.helpUrl,
    targets: v.nodes.map(n => n.target),
    html:    v.nodes.map(n => n.html),
  });

  console.log(JSON.stringify({ wcag: wcag.map(fmt), bp: bp.map(fmt) }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();
