   NOCTURNE — Dark Theme E-Commerce
   ===================================================== */

/* ---- Reset & base ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* Palette */
  --c-bg:          #0c0c0e;
  --c-surface-1:   #131316;
  --c-surface-2:   #1b1b20;
  --c-surface-3:   #242429;
  --c-border:      #2e2e35;
  --c-border-sub:  #1e1e24;

  --c-text:        #f0eee8;
  --c-text-muted:  #9896a4;
  --c-text-sub:    #8a8896; /* lifted from #6b6977 — passes 4.5:1 on all dark surfaces */

  --c-accent:      #c8a96e;   /* warm gold */
  --c-accent-dim:  #8a7045;
  --c-accent-pale: #f5e9cc;

  --c-red:         #e05252;   /* sale badge */
  --c-green:       #4caf50;

  /* Typography */
  --font-serif:    'Georgia', 'Times New Roman', serif;
  --font-sans:     system-ui, -apple-system, 'Segoe UI', Helvetica, Arial, sans-serif;

  /* Spacing */
  --container:     1280px;
  --section-gap:   5rem;

  /* Radii */
  --radius-sm:     4px;
  --radius-md:     8px;
  --radius-lg:     16px;

  /* Transitions */
  --ease:          cubic-bezier(0.4, 0, 0.2, 1);
  --dur:           200ms;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

html {
  scroll-behavior: smooth;
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

body {
  background-color: var(--c-bg);
  color: var(--c-text);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }

ul { list-style: none; }

/* ---- Utility ---- */
.container {
  max-width: var(--container);
  margin-inline: auto;
  padding-inline: clamp(1rem, 5vw, 2.5rem);
}

.sr-only {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
.sr-only:focus,
.sr-only:active {
  clip: auto;
  clip-path: none;
  height: auto;
  overflow: visible;
  position: static;
  white-space: normal;
  width: auto;
}

.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  background: var(--c-accent);
  color: var(--c-bg);
  font-weight: 700;
  padding: 0.75rem 1.25rem;
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  transition: top var(--dur) var(--ease);
}
.skip-link:focus { top: 0; }

/* Focus ring */
:focus-visible {
  outline: 2px solid var(--c-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  border: 2px solid transparent;
  transition: background var(--dur) var(--ease), color var(--dur) var(--ease), border-color var(--dur) var(--ease), transform var(--dur) var(--ease);
}
.btn:focus-visible { outline-offset: 4px; }
.btn:active { transform: scale(0.97); }

.btn-primary {
  background: var(--c-accent);
  color: var(--c-bg);
  border-color: var(--c-accent);
}
.btn-primary:hover { background: var(--c-accent-pale); border-color: var(--c-accent-pale); }

.btn-ghost {
  background: transparent;
  color: var(--c-text);
  border-color: var(--c-border);
}
.btn-ghost:hover { border-color: var(--c-accent); color: var(--c-accent); }

/* ---- Section shared ---- */
.section { padding-block: var(--section-gap); }

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2.5rem;
  flex-wrap: wrap;
}

.section-header h2 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 400;
  letter-spacing: -0.02em;
}

.section-sub {
  color: var(--c-text-muted);
  font-size: 0.9rem;
}

.section-link {
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--c-accent);
  white-space: nowrap;
  transition: color var(--dur) var(--ease);
}
.section-link:hover { color: var(--c-accent-pale); }

/* =====================================================
   HEADER
   ===================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(12, 12, 14, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--c-border-sub);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding-block: 1rem;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}
.logo-mark { color: var(--c-accent); font-size: 1.1rem; }
.logo-text  {
  font-family: var(--font-serif);
  font-size: 1.1rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

/* Primary nav */
nav[aria-label="Primary"] { flex: 1; display: flex; justify-content: center; }

.nav-toggle {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  color: var(--c-text);
  flex-direction: column;
  gap: 5px;
}
.hamburger,
.hamburger::before,
.hamburger::after {
  display: block;
  width: 22px;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform var(--dur) var(--ease), opacity var(--dur) var(--ease);
}
.hamburger { position: relative; }
.hamburger::before,
.hamburger::after {
  content: '';
  position: absolute;
  left: 0;
}
.hamburger::before { top: -6px; }
.hamburger::after  { top:  6px; }

.nav-toggle[aria-expanded="true"] .hamburger { background: transparent; }
.nav-toggle[aria-expanded="true"] .hamburger::before { transform: rotate(45deg) translate(4px, 4px); }
.nav-toggle[aria-expanded="true"] .hamburger::after  { transform: rotate(-45deg) translate(4px, -4px); }

.nav-list {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-list > li { position: relative; }

.nav-list a,
.submenu-trigger {
  display: block;
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--c-text-muted);
  letter-spacing: 0.02em;
  background: none;
  border: none;
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: color var(--dur) var(--ease), background var(--dur) var(--ease);
  white-space: nowrap;
}
.nav-list a:hover,
.submenu-trigger:hover,
.nav-list a[aria-current="page"] {
  color: var(--c-text);
  background: var(--c-surface-2);
}
.nav-list a[aria-current="page"] {
  text-decoration: underline;
  text-decoration-color: var(--c-accent);
  text-underline-offset: 4px;
}

.chevron { font-style: normal; transition: transform var(--dur) var(--ease); }
.submenu-trigger[aria-expanded="true"] .chevron { transform: rotate(-180deg); }

.submenu {
  position: absolute;
  top: calc(100% + 0.5rem);
  left: 0;
  min-width: 180px;
  background: var(--c-surface-2);
  border: 1px solid var(--c-border);
  border-radius: var(--radius-md);
  padding: 0.5rem;
  box-shadow: 0 8px 32px rgba(0,0,0,0.5);
}
.submenu li a {
  border-radius: var(--radius-sm);
  color: var(--c-text-muted);
}
.submenu li a:hover { color: var(--c-text); background: var(--c-surface-3); }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: 0.25rem; margin-left: auto; }

.icon-btn {
  position: relative;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--c-text-muted);
  padding: 0.5rem;
  border-radius: var(--radius-sm);
  transition: color var(--dur) var(--ease), background var(--dur) var(--ease);
  display: flex;
  align-items: center;
  justify-content: center;
}
.icon-btn:hover { color: var(--c-text); background: var(--c-surface-2); }

.cart-count {
  position: absolute;
  top: 2px;
  right: 2px;
  background: var(--c-accent);
  color: var(--c-bg);
  font-size: 0.6rem;
  font-weight: 700;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* =====================================================
   HERO
   ===================================================== */
.hero {
  position: relative;
  min-height: clamp(480px, 85vh, 900px);
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-gradient {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 80% at 70% 50%, rgba(200, 169, 110, 0.08) 0%, transparent 60%),
    radial-gradient(ellipse 60% 100% at 100% 100%, rgba(100, 80, 180, 0.06) 0%, transparent 60%),
    linear-gradient(160deg, #0c0c0e 0%, #16141c 50%, #0c0c0e 100%);
}

.hero-pattern {
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(
      0deg,
      transparent,
      transparent 79px,
      rgba(255,255,255,0.015) 79px,
      rgba(255,255,255,0.015) 80px
    ),
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 79px,
      rgba(255,255,255,0.015) 79px,
      rgba(255,255,255,0.015) 80px
    );
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 660px;
  padding-block: 6rem;
}

.hero-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--c-accent);
  margin-bottom: 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.hero-eyebrow::before {
  content: '';
  display: block;
  width: 2.5rem;
  height: 1px;
  background: var(--c-accent);
}

.hero h1 {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 7vw, 5.5rem);
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: 1.5rem;
}
.hero h1 em {
  font-style: italic;
  color: var(--c-accent);
}

.hero-sub {
  font-size: 1.0625rem;
  color: var(--c-text-muted);
  max-width: 42ch;
  margin-bottom: 2.5rem;
  line-height: 1.7;
}

.hero-ctas { display: flex; gap: 1rem; flex-wrap: wrap; }

.hero-scroll-cue {
  position: absolute;
  bottom: 2rem;
  left: clamp(1rem, 5vw, 2.5rem);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--c-text-sub);
  font-size: 0.7rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}
.scroll-line {
  width: 1px;
  height: 2.5rem;
  background: linear-gradient(to bottom, transparent, var(--c-text-sub));
  animation: scrollPulse 2s infinite;
}
@keyframes scrollPulse {
  0%, 100% { opacity: 0.3; }
  50%       { opacity: 1; }
}

/* =====================================================
   MARQUEE BAR
   ===================================================== */
.marquee-bar {
  background: var(--c-surface-1);
  border-block: 1px solid var(--c-border-sub);
  padding-block: 0.75rem;
  overflow: hidden;
  white-space: nowrap;
