  border-radius: 50%;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  backdrop-filter: blur(8px);
  transition: color var(--dur) var(--ease), background var(--dur) var(--ease), border-color var(--dur) var(--ease);
  /* Don't let the button inherit the <a> link underline */
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] {
  color: var(--c-red);
  border-color: var(--c-red);
  background: rgba(224,82,82,0.12);
}
.product-wishlist[aria-pressed="true"] svg { fill: var(--c-red); stroke: var(--c-red); }

.product-card__body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  flex: 1;
}

.product-category {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--c-accent);
}

.product-name {
  font-family: var(--font-serif);
  font-weight: 400;
  font-size: 1.125rem;
  line-height: 1.2;
}

.product-desc {
  font-size: 0.8125rem;
  color: var(--c-text-muted);
  line-height: 1.5;
  flex: 1;
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.5rem;
  padding-top: 0.75rem;
